export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key) => String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
  const args = String(inputs.commandArgs === undefined || inputs.commandArgs === null ? '' : inputs.commandArgs).trim();
  const miniappUrl = String(inputs.miniappUrl === undefined || inputs.miniappUrl === null ? '' : inputs.miniappUrl);
  // Аргумент команды — только валидный slug ивента; всё остальное = новый ивент.
  // Права на правку решает manage-api по initData и owner_id, не эта кнопка.
  const SLUG = /^[A-Za-z0-9_]{1,12}$/;
  const eventId = SLUG.test(args) ? args : '';
  const url = miniappUrl + 'manage.html' + (eventId ? ('?event_id=' + eventId) : '');
  return {
    text: t(eventId ? 'manage.open.edit' : 'manage.open.new'),
    replyMarkup: { inline_keyboard: [[{ text: t('manage.open.btn'), web_app: { url: url } }]] },
    eventId: eventId, url: url
  };
};
